use std::{io::{Read,Write},path::PathBuf,process::Command,sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}},time::Duration};
use serde_json::{json,Value};
static FIXTURE_SEQUENCE:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);
struct Fixture{folder:PathBuf,origin:String,requests:Arc<Mutex<Vec<String>>>,stop:Arc<AtomicBool>,worker:Option<std::thread::JoinHandle<()>>}
impl Fixture{fn new()->Self{let folder=std::env::temp_dir().join(format!("fitig-batch-cli-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),FIXTURE_SEQUENCE.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir(&folder).unwrap();let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let origin=format!("http://{}",listener.local_addr().unwrap());listener.set_nonblocking(true).unwrap();let stop=Arc::new(AtomicBool::new(false));let requests=Arc::new(Mutex::new(Vec::new()));let running=stop.clone();let seen=requests.clone();let worker=std::thread::spawn(move||{while !running.load(Ordering::Relaxed){let(mut stream,_)=match listener.accept(){Ok(value)=>value,Err(error)if error.kind()==std::io::ErrorKind::WouldBlock=>{std::thread::sleep(Duration::from_millis(5));continue},Err(error)=>panic!("{error}")};stream.set_nonblocking(false).unwrap();stream.set_read_timeout(Some(Duration::from_secs(5))).unwrap();let mut head=Vec::new();let mut byte=[0];while !head.ends_with(b"\r\n\r\n"){if stream.read_exact(&mut byte).is_err(){break}head.push(byte[0]);}let text=String::from_utf8_lossy(&head);let target=text.split_whitespace().nth(1).unwrap_or("/").to_string();seen.lock().unwrap().push(target.clone());if target=="/slow"{std::thread::sleep(Duration::from_millis(400))}let body=if target=="/robots.txt"{"User-agent: *\nAllow: /"}else if target=="/a"{"<meta charset='utf-8'><title>בית</title><a href='/שלום'>ילד</a>"}else if target=="/list"{"<title>List</title><a href='/must-not-fetch'>not explicit</a>"}else{"<meta charset='utf-8'><title>עברית</title>"};let _=write!(stream,"HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len());}});Self{folder,origin,requests,stop,worker:Some(worker)}}
 fn run(&self,manifest:Value,name:&str)->std::process::Output{let file=self.folder.join(format!("{name}.json"));std::fs::write(&file,serde_json::to_vec(&manifest).unwrap()).unwrap();Command::new(env!("CARGO_BIN_EXE_fitig-engine")).args(["batch","--manifest",file.to_str().unwrap(),"--out",self.folder.join(name).to_str().unwrap()]).output().unwrap()}}
impl Drop for Fixture{fn drop(&mut self){self.stop.store(true,Ordering::Relaxed);if let Some(worker)=self.worker.take(){worker.join().unwrap()}let _=std::fs::remove_dir_all(&self.folder);}}
#[test]fn cli_runs_sequential_spider_list_exports_and_preserves_existing_root(){let f=Fixture::new();let manifest=json!({"version":1,"exports":["csv","html","xlsx","sitemap"],"jobs":[{"name":"סריקה","url":format!("{}/a",f.origin),"delay_ms":0,"concurrency":1},{"name":"List","url":format!("{}/list",f.origin),"urls":[format!("{}/list",f.origin),format!("{}/leaf",f.origin)],"delay_ms":0}]});let output=f.run(manifest.clone(),"success");assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let report:Value=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(report["status"],"completed");for job in report["jobs"].as_array().unwrap(){assert_eq!(job["completed"],2);assert_eq!(job["exports"].as_array().unwrap().len(),4)}let folder=f.folder.join("success");let xml=std::fs::read_to_string(folder.join("job-001/report.xml")).unwrap();assert!(xml.contains("שלום")&&!xml.contains("%D7"));assert!(std::fs::read(folder.join("job-001/report.xlsx")).unwrap().starts_with(b"PK"));let csv=std::fs::read_to_string(folder.join("job-001/report.csv")).unwrap();assert!(csv.contains("עברית"));assert!(!f.requests.lock().unwrap().iter().any(|url|url=="/must-not-fetch"));let before=std::fs::read(folder.join("batch-status.json")).unwrap();let count=f.requests.lock().unwrap().len();assert!(!f.run(manifest,"success").status.success());assert_eq!(std::fs::read(folder.join("batch-status.json")).unwrap(),before);assert_eq!(f.requests.lock().unwrap().len(),count);}
#[test]fn cli_failure_stops_or_continues_without_faking_success(){let f=Fixture::new();let closed=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let unavailable=format!("http://{}/",closed.local_addr().unwrap());drop(closed);for (name,proceed,expected) in [("stop",false,"skipped"),("continue",true,"completed")]{let manifest=json!({"version":1,"continue_on_error":proceed,"jobs":[{"name":"unavailable","url":unavailable},{"name":"owned","url":format!("{}/a",f.origin),"delay_ms":0}]});let output=f.run(manifest,name);assert!(!output.status.success());let report:Value=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(report["status"],"failed");assert_eq!(report["jobs"][0]["status"],"failed");assert_eq!(report["jobs"][0]["queued"],1);assert_eq!(report["jobs"][1]["status"],expected);}}
#[test]fn cli_limits_stop_marker_and_validation_are_explicit(){let f=Fixture::new();let output=f.run(json!({"version":1,"exports":["csv"],"jobs":[{"name":"limited","url":format!("{}/a",f.origin),"limit":1,"delay_ms":0}]}),"limited");assert!(!output.status.success());let report:Value=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(report["status"],"limited");assert_eq!(report["jobs"][0]["queued"],1);let invalid=f.run(json!({"version":1,"jobs":[{"name":"invalid","url":"https://user:password@e.test/"}]}),"invalid");assert!(!invalid.status.success()&&!f.folder.join("invalid").exists());let manifest=f.folder.join("cancel.json");std::fs::write(&manifest,serde_json::to_vec(&json!({"version":1,"jobs":[{"name":"slow","url":format!("{}/slow",f.origin),"delay_ms":0},{"name":"skipped","url":format!("{}/a",f.origin)}]})).unwrap()).unwrap();let root=f.folder.join("cancel");let child=Command::new(env!("CARGO_BIN_EXE_fitig-engine")).args(["batch","--manifest",manifest.to_str().unwrap(),"--out",root.to_str().unwrap()]).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped()).spawn().unwrap();let mut observed=false;for _ in 0..500{if f.requests.lock().unwrap().iter().any(|url|url=="/slow"){observed=true;break}std::thread::sleep(Duration::from_millis(10))}assert!(observed);std::fs::write(root.join("batch.stop"),b"stop").unwrap();let output=child.wait_with_output().unwrap();assert!(!output.status.success());let report:Value=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(report["status"],"stopped");assert_eq!(report["jobs"][1]["status"],"skipped");}
